// may be more efficient than using camel_folder_append_message_sync().
func (x *Folder) TransferMessagesToSync(MessageUidsVar uintptr, DestinationVar *Folder, DeleteOriginalsVar bool, TransferredUidsVar *uintptr, CancellableVar *gio.Cancellable) (bool, error) {
	var cerr *glib.Error

	cret := xFolderTransferMessagesToSync(x.GoPointer(), MessageUidsVar, DestinationVar.GoPointer(), DeleteOriginalsVar, TransferredUidsVar, CancellableVar.GoPointer(), &cerr)
	if cerr == nil {
		return cret, nil
	}
	return cret, cerr

}

var xFolderUnlock func(uintptr)

// Unlocks @folder, previously locked with camel_folder_lock().
func (x *Folder) Unlock() {

	xFolderUnlock(x.GoPointer())

}

func (c *Folder) GoPointer() uintptr {
	if c == nil {
		return 0
	}
	return c.Ptr
}

func (c *Folder) SetGoPointer(ptr uintptr) {
	c.Ptr = ptr
}

